"""Bounded integer event import API, current implementation."""
import copy
import re

def new_state():
    return {"events": {}, "totals": {}}

def _event(value, path):
    if type(value) is not dict or set(value) != {"id", "revision", "account", "amount"}:
        raise ValueError(path + ":event_shape")
    for field in ("id", "account"):
        if type(value[field]) is not str or not re.fullmatch(r"[A-Za-z][A-Za-z0-9_]{0,15}", value[field]):
            raise ValueError(path + "." + field + ":invalid_name")
    if type(value["revision"]) is not int or not 0 <= value["revision"] <= 1000:
        raise ValueError(path + ".revision:integer_range")
    if type(value["amount"]) is not int or not -1000 <= value["amount"] <= 1000:
        raise ValueError(path + ".amount:integer_range")

def apply_batch(state, batch):
    if type(batch) is not list or len(batch) > 8:
        raise ValueError("batch:invalid_size")

    # First pass: validate all events and plan changes
    # Track what we need to remove and what we need to add
    to_remove = set()
    to_add = {}
    conflict = False
    conflict_path = None

    for index, event in enumerate(batch):
        path = "batch[" + str(index) + "]"
        _event(event, path)

        old = state["events"].get(event["id"])

        if old is not None and event["revision"] < old["revision"]:
            # Lower revision - skip this event (ignore it)
            continue

        if old is not None and event["revision"] == old["revision"] and event != old:
            # Conflict - reject entire batch
            conflict = True
            conflict_path = path
            break

        # Mark for removal (if exists) and addition
        to_remove.add(event["id"])
        to_add[event["id"]] = copy.deepcopy(event)

    if conflict:
        raise ValueError(conflict_path + ":revision_conflict")

    # If no changes needed, return None
    if not to_remove and not to_add:
        return None

    # Apply removals first (subtract old amounts from totals)
    for eid in to_remove:
        old_event = state["events"].get(eid)
        if old_event is not None:
            account = old_event["account"]
            state["totals"][account] = state["totals"].get(account, 0) - old_event["amount"]
            # Only remove account if it's now zero (and has no other events)
            # We'll check this after all removals

    # Apply additions (add new amounts to totals)
    for eid, event in to_add.items():
        account = event["account"]
        state["totals"][account] = state["totals"].get(account, 0) + event["amount"]
        state["events"][eid] = event

    # Clean up zero totals after all additions
    for account in list(state["totals"].keys()):
        if state["totals"][account] == 0:
            del state["totals"][account]

    return None

def snapshot(state):
    return {"events": [copy.deepcopy(state["events"][key]) for key in sorted(state["events"])],
            "totals": dict(sorted(state["totals"].items()))}

