import copy
import re

def new_state():
    return {"events": {}, "totals": {}}

def _event(value, path):
    if type(value) is not dict or set(value) != {"id", "revision", "account", "amount"}:
        raise ValueError(path + ":event_shape")
    for field in ("id", "account"):
        if type(value[field]) is not str or not re.fullmatch(r"[A-Za-z][A-Za-z0-9_]{0,15}", value[field]):
            raise ValueError(path + "." + field + ":invalid_name")
    if type(value["revision"]) is not int or not 0 <= value["revision"] <= 1000:
        raise ValueError(path + ".revision:integer_range")
    if type(value["amount"]) is not int or not -1000 <= value["amount"] <= 1000:
        raise ValueError(path + ".amount:integer_range")

def apply_batch(state, batch):
    if type(batch) is not list or len(batch) > 8:
        raise ValueError("batch:invalid_size")

    # First, validate entire batch and collect errors
    errors = []
    for index, event in enumerate(batch):
        path = "batch[" + str(index) + "]"
        try:
            _event(event, path)
        except ValueError as e:
            errors.append(str(e))

    if errors:
        raise ValueError(errors[0])

    # Check store capacity (max 8 unique event IDs)
    current_ids = set(state["events"].keys())
    batch_ids = {event["id"] for event in batch}
    if len(current_ids | batch_ids) > 8:
        raise ValueError("batch:store_capacity")

    # Now apply atomically - validate all revisions and conflicts first
    # Build a map of events we're about to add
    new_events = {}
    for event in batch:
        eid = event["id"]
        if eid in current_ids:
            old = state["events"][eid]
            if event["revision"] < old["revision"]:
                # Lower revision, skip this event but continue to next
                raise ValueError("batch:revision_conflict")
            if event["revision"] == old["revision"] and event != old:
                raise ValueError("batch:revision_conflict")
            # Same revision and same content - idempotent, skip
            continue
        new_events[eid] = event

    # Check capacity after filtering out skipped events
    if len(current_ids | set(new_events.keys())) > 8:
        raise ValueError("batch:store_capacity")

    # Now apply atomically
    for event in batch:
        path = "batch[" + str(event["id"]) + "]"
        eid = event["id"]
        old = state["events"].get(eid)

        if old is not None:
            if event["revision"] < old["revision"]:
                # Lower revision, skip this event but continue to next
                continue
            if event["revision"] == old["revision"] and event != old:
                raise ValueError(path + ":revision_conflict")
            # Same revision and same content - idempotent, skip
            continue

        # Adjust totals for the old contribution (if any)
        if old is not None:
            _adjust_totals(state, event["account"], -old["amount"])

        # Add the new event
        state["events"][event["id"]] = copy.deepcopy(event)
        account = event["account"]
        state["totals"][account] = state["totals"].get(account, 0) + event["amount"]

def _adjust_totals(state, account, delta):
    """Remove old contribution from account, then add new amount."""
    if account in state["totals"]:
        # Remove old contribution
        state["totals"][account] -= delta
    # Add new amount
    state["totals"][account] += delta

def snapshot(state):
    return {"events": [copy.deepcopy(state["events"][key]) for key in sorted(state["events"])],
            "totals": dict(sorted(state["totals"].items()))}

