#!/usr/bin/env python3
"""Member test suite for rules module."""
import sys
import os

# Add parent directory to path to import rules
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from rules import evaluate, validate_rule

def test_range_upper_inclusive():
    """Test that range upper bound is inclusive."""
    rule = {"op": "between", "path": "x", "low": 1, "high": 3}
    doc = {"x": 3}
    result = evaluate(rule, doc)
    assert result == True, f"Expected True for x=3 in range [1,3], got {result}"

def test_range_singleton():
    """Test that range singleton (low==high) is inclusive."""
    rule = {"op": "between", "path": "x", "low": 4, "high": 4}
    doc = {"x": 4}
    result = evaluate(rule, doc)
    assert result == True, f"Expected True for x=4 in range [4,4], got {result}"

def test_range_nested_error_path():
    """Test that nested error reports correct path."""
    rule = {"op": "all", "rules": [
        {"op": "eq", "path": "x", "value": 1},
        {"op": "between", "path": "x", "low": 3, "high": 1}
    ]}
    doc = {"x": 0}
    try:
        evaluate(rule, doc)
        assert False, "Expected ValueError"
    except ValueError as e:
        assert str(e) == "$.rules[1].high:invalid_range", f"Expected $.rules[1].high:invalid_range, got {e}"

def test_range_lower_bound():
    """Test that range lower bound is inclusive."""
    rule = {"op": "between", "path": "x", "low": 1, "high": 3}
    doc = {"x": 1}
    result = evaluate(rule, doc)
    assert result == True, f"Expected True for x=1 in range [1,3], got {result}"

def test_range_outside_upper():
    """Test that values above upper bound fail."""
    rule = {"op": "between", "path": "x", "low": 1, "high": 3}
    doc = {"x": 4}
    result = evaluate(rule, doc)
    assert result == False, f"Expected False for x=4 in range [1,3], got {result}"

def test_range_outside_lower():
    """Test that values below lower bound fail."""
    rule = {"op": "between", "path": "x", "low": 1, "high": 3}
    doc = {"x": 0}
    result = evaluate(rule, doc)
    assert result == False, f"Expected False for x=0 in range [1,3], got {result}"

def test_eq_operator():
    """Test equality operator."""
    rule = {"op": "eq", "path": "x", "value": 5}
    doc = {"x": 5}
    result = evaluate(rule, doc)
    assert result == True, f"Expected True for x=5 eq 5, got {result}"

def test_eq_type_strict():
    """Test that equality is type-strict."""
    rule = {"op": "eq", "path": "x", "value": True}
    doc = {"x": 1}
    result = evaluate(rule, doc)
    assert result == False, f"Expected False for x=1 eq True, got {result}"

def test_eq_null():
    """Test equality with null."""
    rule = {"op": "eq", "path": "x", "value": None}
    doc = {"x": None}
    result = evaluate(rule, doc)
    assert result == True, f"Expected True for x=null eq null, got {result}"

def test_exists_null():
    """Test exists with null value."""
    rule = {"op": "exists", "path": "x"}
    doc = {"x": None}
    result = evaluate(rule, doc)
    assert result == True, f"Expected True for exists x when x=null, got {result}"

def test_exists_missing():
    """Test exists with missing key."""
    rule = {"op": "exists", "path": "x"}
    doc = {"y": 1}
    result = evaluate(rule, doc)
    assert result == False, f"Expected False for exists x when missing, got {result}"

def test_all_operator():
    """Test all operator."""
    rule = {"op": "all", "rules": [
        {"op": "eq", "path": "x", "value": 1},
        {"op": "eq", "path": "y", "value": 2}
    ]}
    doc = {"x": 1, "y": 2}
    result = evaluate(rule, doc)
    assert result == True, f"Expected True for all conditions, got {result}"

def test_any_operator():
    """Test any operator."""
    rule = {"op": "any", "rules": [
        {"op": "eq", "path": "x", "value": 1},
        {"op": "eq", "path": "y", "value": 2}
    ]}
    doc = {"x": 1}
    result = evaluate(rule, doc)
    assert result == True, f"Expected True for any condition, got {result}"

def test_not_operator():
    """Test not operator."""
    rule = {"op": "not", "rule": {"op": "eq", "path": "x", "value": 1}}
    doc = {"x": 2}
    result = evaluate(rule, doc)
    assert result == True, f"Expected True for not(x==1) when x=2, got {result}"

def test_validate_rule_errors():
    """Test validation error messages."""
    # Test invalid path
    try:
        validate_rule({"op": "eq", "path": "invalid-path", "value": 1})
        assert False, "Expected ValueError for invalid path"
    except ValueError as e:
        assert str(e) == "$.path:invalid_path", f"Expected $.path:invalid_path, got {e}"

def test_document_object_required():
    """Test that document must be an object."""
    rule = {"op": "eq", "path": "x", "value": 1}
    try:
        evaluate(rule, "not a dict")
        assert False, "Expected ValueError for non-object document"
    except ValueError as e:
        assert str(e) == "document:object_required", f"Expected document:object_required, got {e}"

if __name__ == "__main__":
    tests = [
        test_range_upper_inclusive,
        test_range_singleton,
        test_range_nested_error_path,
        test_range_lower_bound,
        test_range_outside_upper,
        test_range_outside_lower,
        test_eq_operator,
        test_eq_type_strict,
        test_eq_null,
        test_exists_null,
        test_exists_missing,
        test_all_operator,
        test_any_operator,
        test_not_operator,
        test_validate_rule_errors,
        test_document_object_required,
    ]

    passed = 0
    failed = 0

    for test in tests:
        try:
            test()
            print(f"PASS: {test.__name__}")
            passed += 1
        except AssertionError as e:
            print(f"FAIL: {test.__name__}: {e}")
            failed += 1
        except Exception as e:
            print(f"ERROR: {test.__name__}: {e}")
            failed += 1

    print(f"\n{passed} passed, {failed} failed")
    sys.exit(0 if failed == 0 else 1)

