def migrate_v1_to_v2(rule):
    # Validate v1 rule before conversion
    if not isinstance(rule, dict):
        raise ValueError("$:object_required")

    # Validate depth and node limits
    def count_nodes(node, depth=0):
        count = 0
        if depth > 4:
            raise ValueError(":depth_limit")
        if isinstance(node, dict):
            count += 1
            if "rules" in node:
                for child in node["rules"]:
                    count += count_nodes(child, depth + 1)
            elif "rule" in node:
                count += count_nodes(node["rule"], depth + 1)
        return count

    total_nodes = count_nodes(rule)
    if total_nodes > 16:
        raise ValueError(":node_limit")

    def validate_node(node, path="$"):
        if not isinstance(node, dict):
            raise ValueError(f"{path}:object_required")

        op = node.get("op")
        if op is None:
            raise ValueError(f"{path}.op:missing")

        if op not in ("eq", "exists", "between", "all", "any", "not"):
            raise ValueError(f"{path}.op:unknown")

        if op == "eq":
            if "path" not in node:
                raise ValueError(f"{path}.path:missing")
            if "value" not in node:
                raise ValueError(f"{path}.value:missing")
            value = node["value"]
            if value is None or not isinstance(value, (bool, int, str)) or isinstance(value, bool):
                if isinstance(value, bool):
                    raise ValueError(f"{path}.value:scalar_required")
                elif value is None:
                    raise ValueError(f"{path}.value:scalar_required")
                else:
                    raise ValueError(f"{path}.value:scalar_required")
            if isinstance(value, str) and len(value) > 32:
                raise ValueError(f"{path}.value:scalar_required")
        elif op == "exists":
            if "path" not in node:
                raise ValueError(f"{path}.path:missing")
        elif op == "between":
            if "path" not in node:
                raise ValueError(f"{path}.path:missing")
            if "low" not in node:
                raise ValueError(f"{path}.low:missing")
            if "high" not in node:
                raise ValueError(f"{path}.high:missing")
            low, high = node["low"], node["high"]
            if isinstance(low, bool) or not isinstance(low, int):
                raise ValueError(f"{path}.low:integer_required")
            if isinstance(high, bool) or not isinstance(high, int):
                raise ValueError(f"{path}.high:integer_required")
            if low > high:
                raise ValueError(f"{path}.high:invalid_range")
        elif op in ("all", "any"):
            if "rules" not in node:
                raise ValueError(f"{path}.rules:rule_list_required")
            if len(node["rules"]) < 1 or len(node["rules"]) > 4:
